 35	func TestSemanticGraphCypherPredicatesDirectionsAndLimits(t *testing.T) {
 36		forward := `MATCH (a)-[r]->(b) WHERE a.name = "Caller" AND a.kind = "function" AND a.file_path CONTAINS "internal" AND b.qualified_name = "pkg.Target" AND b.kind = "method" AND b.language CONTAINS "Go" AND r.type = "calls" AND r.reason CONTAINS "first" AND r.reason CONTAINS "second" RETURN a,r,b LIMIT 3`
 37		filters, ok := parseCypherGraphQuery(forward)
 38		if !ok {
 39			t.Fatal("forward Cypher query was not parsed")
 40		}
 41		if filters.FromName != "Caller" || filters.FromKind != "function" || filters.FromNameContains != "internal" || filters.ToName != "pkg.Target" || filters.ToKind != "method" || filters.ToNameContains != "Go" || filters.Type != "CALLS" || filters.Text != "first second" || filters.Limit != 3 {
 42			t.Fatalf("forward filters = %+v", filters)
 43		}
 44	
 45		reverse, ok := parseCypherGraphQuery(`MATCH (a)<-[r:USES_TYPE]-(b) WHERE a.qualified_name = "pkg.Target" AND b.name CONTAINS "Caller" RETURN count(r) LIMIT 1`)
 46		if !ok || !reverse.Count || reverse.Type != "USES_TYPE" || reverse.ToName != "pkg.Target" || reverse.FromNameContains != "Caller" || reverse.Limit != 1 {
 47			t.Fatalf("reverse filters = %+v ok=%t", reverse, ok)
 48		}
 49		for _, invalid := range []string{"plain text", `MATCH (a)-[r]-(b) RETURN r`, `MATCH (a)->[r]-(b) RETURN r`} {
 50			if got, ok := parseCypherGraphQuery(invalid); ok {
 51				t.Fatalf("invalid query parsed: %q => %+v", invalid, got)
 52			}
 53		}
 54	}
