12	func TestSemanticRefreshIdentityWithUnchangedTree(t *testing.T) {
13		repo := t.TempDir()
14		env := semanticTestEnv(t, repo)
15		runner := semanticFixtureRunner(repo, semanticFixtureSnapshot("1.0"))
16		opts := Options{Env: env, Runner: runner, Now: time.Now}
17		ctx := context.Background()
18		if err := runSemanticIndex(ctx, &cobra.Command{}, opts, semanticIndexOptions{graphBinary: "entire"}, repo); err != nil {
19			t.Fatal(err)
20		}
21		brain := filepath.Join(env.PluginDataDir, repoStoreDirName, "gh", "example", "repo")
22		manifest, err := loadBrainManifest(brain)
23		if err != nil {
24			t.Fatal(err)
25		}
26		if needed, _, err := semanticRefreshNeeded(ctx, opts, brain, repo, manifest, false, "entire"); err != nil || needed {
27			t.Fatalf("legacy unchanged tree: %v %v", needed, err)
28		}
29		key := fakeCommandKey("entire", "graph", "version", "--json")
30		runner.responses[key] = fakeCommandResponse{err: errors.New("unknown graph version command")}
31		needed, warning, err := semanticRefreshNeeded(ctx, opts, brain, repo, manifest, false, "entire")
32		if err != nil || needed || warning == "" {
33			t.Fatalf("probe failure aborted warm reuse: %v %q %v", needed, warning, err)
34		}
35		runner.responses[fakeCommandKey("git", "rev-parse", "HEAD^{tree}")] = fakeCommandResponse{stdout: "changed-tree\n"}
36		needed, warning, err = semanticRefreshNeeded(ctx, opts, brain, repo, manifest, false, "entire")
37		if err != nil || !needed || warning == "" {
38			t.Fatalf("probe failure masked changed tree: %v %q %v", needed, warning, err)
39		}
40		runner.responses[fakeCommandKey("git", "rev-parse", "HEAD^{tree}")] = fakeCommandResponse{stdout: "tree111\n"}
41		cancelled, cancel := context.WithCancel(ctx)
42		cancel()
43		if _, _, err := semanticRefreshNeeded(cancelled, opts, brain, repo, manifest, false, "entire"); !errors.Is(err, context.Canceled) {
44			t.Fatalf("cancellation swallowed: %v", err)
