 16	func semanticRegressionPathDigest(t *testing.T, repoDir, clean string, ignore brainIgnore) ([32]byte, int64) {
 17		t.Helper()
 18		h := sha256.New()
 19		var total int64
 20		if err := appendWorktreePathContent(h, &total, repoDir, clean, ignore); err != nil {
