    26			`INSERT INTO runtime_traces(imported_at,source_path,from_id,to_id,observed_type,matched_static_edge) VALUES ('2026-09-18T00:01:00Z','traces/run.ndjson','target-id','caller-id','OBSERVED_CALL',0)`,
    27		} {
