    84	func TestSemanticRuntimeTraceFiltersMatchAndRejectEachEndpoint(t *testing.T) {
    85		db := semanticRegressionGraphDB(t)
    86		filters := graphQueryFilters{
    87			Type: "RUNTIME_TRACE", From: "target-id", To: "caller-id", Text: "run.ndjson", FromName: "Target", ToName: "Caller",
    88			FromKind: "method", ToKind: "function", FromNameContains: "target.go", ToNameContains: "caller.go",
