    28	func TestSemanticWorktreePathFingerprintIncludesFilesAndExcludesIgnoredAndSymlinks(t *testing.T) {
    29		repoDir := t.TempDir()
    30		for rel, body := range map[string]string{
    31			"untracked/kept.go":          "package kept\n",
    32			"untracked/ignored/key.pem":  "secret-one\n",
    33			"untracked/ignored-file.pem": "secret-one\n",
    34		} {
    35			path := filepath.Join(repoDir, filepath.FromSlash(rel))
    36			if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
    37				t.Fatal(err)
    38			}
    39			if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
    40				t.Fatal(err)
    41			}
    42		}
    43		ignore := brainIgnore{patterns: []string{"untracked/ignored/**", "untracked/ignored-file.pem"}}
    44		base, baseBytes := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
    45		if baseBytes == 0 {
    46			t.Fatal("included worktree file contributed no fingerprint bytes")
    47		}
    48		if _, singleBytes := semanticRegressionPathDigest(t, repoDir, "untracked/kept.go", ignore); singleBytes == 0 {
    49			t.Fatal("top-level untracked file contributed no fingerprint bytes")
    50		}
    51		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "kept.go"), []byte("package changed\n"), 0o600); err != nil {
    52			t.Fatal(err)
    53		}
    54		included, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
    55		if included == base {
    56			t.Fatal("changing an included file did not change the worktree fingerprint")
    57		}
    58		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "ignored", "key.pem"), []byte("secret-two\n"), 0o600); err != nil {
    59			t.Fatal(err)
    60		}
    61		ignored, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
    62		if ignored != included {
    63			t.Fatal("changing an ignored file changed the worktree fingerprint")
    64		}
    65		if err := os.WriteFile(filepath.Join(repoDir, "untracked", "ignored-file.pem"), []byte("secret-two\n"), 0o600); err != nil {
    66			t.Fatal(err)
    67		}
    68		ignoredFile, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
    69		if ignoredFile != ignored {
    70			t.Fatal("changing an ignored sibling file changed the worktree fingerprint")
    71		}
    72		missing, missingBytes := semanticRegressionPathDigest(t, repoDir, "missing", ignore)
    73		if missing != sha256.Sum256(nil) || missingBytes != 0 {
    74			t.Fatalf("missing path contributed to fingerprint: %x bytes=%d", missing, missingBytes)
    75		}
    76		t.Run("symlink paths", func(t *testing.T) {
    77			external := filepath.Join(t.TempDir(), "external.go")
    78			if err := os.WriteFile(external, []byte("external-one\n"), 0o600); err != nil {
    79				t.Fatal(err)
    80			}
    81			symlink := filepath.Join(repoDir, "untracked", "linked.go")
    82			if err := os.Symlink(external, symlink); err != nil {
    83				t.Skipf("symlink unavailable: %v", err)
    84			}
    85			if directLink, linkBytes := semanticRegressionPathDigest(t, repoDir, "untracked/linked.go", ignore); directLink != sha256.Sum256(nil) || linkBytes != 0 {
    86				t.Fatalf("top-level symlink contributed to fingerprint: %x bytes=%d", directLink, linkBytes)
    87			}
    88			if err := os.WriteFile(external, []byte("external-two\n"), 0o600); err != nil {
    89				t.Fatal(err)
    90			}
    91			linked, _ := semanticRegressionPathDigest(t, repoDir, "untracked", ignore)
    92			if linked != ignoredFile {
    93				t.Fatal("changing a symlink target outside the repository changed the fingerprint")
    94			}
    95		})
    96	}
