 18	func semanticMultiRemoteFixtureRunner(repoDir, snapshot string, remotes map[string]string) *fakeCommandRunner {
 19		runner := semanticFixtureRunner(repoDir, snapshot)
 20		if origin, ok := remotes["origin"]; ok {
 21			runner.responses[fakeCommandKey("git", "remote", "get-url", "origin")] = fakeCommandResponse{stdout: origin + "\n"}
