145		repoDir := t.TempDir()
146		env := semanticTestEnv(t, repoDir)
147		runner := semanticMultiRemoteFixtureRunner(repoDir, semanticFixtureSnapshot("1.0"), map[string]string{}) // header says gh/example/repo
148		runner.responses[fakeCommandKey("entire", "graph", "doctor", "--json")] = fakeCommandResponse{
149			stdout: `{"no_egress":true,"repo_key":"local/somewhere-else"}`,
150		}
151		cmd := &cobra.Command{Use: "index"}
152		opts := Options{Env: env, Runner: runner, Now: time.Now}
153	
154		err := runSemanticIndex(cmd.Context(), cmd, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir)
155		if err == nil {
