169	// the header is ever handed on, so comparing it against that same storage key
170	// downstream compared a value with itself. A check that cannot fail is worse
171	// than no check: it reads as protection and provides none. The real assertions
172	// are validateSemanticProviderRepoKey (the provider's untrusted spelling) and
173	// readSemanticSnapshotSummary / validateImportedBundle (untrusted on-disk keys).
174	func TestLiveHeaderRepoKeyCheckCannotFail(t *testing.T) {
175		const storageKey = "gl/acme/widget"
176		var out strings.Builder
177		res, err := scanSemanticStream(
178			strings.NewReader(providerLocalKeyFixtureSnapshot("/tmp/widget")),
179			&out,
180			semanticStreamScanConfig{repoKey: storageKey, repoDir: "/tmp/widget"},
181		)
182		if err != nil {
183			t.Fatalf("scan: %v", err)
184		}
185		if res.header.RepoKey != storageKey {
186			t.Fatalf("header repo_key = %q; scanSemanticStream must normalize it to the storage key %q", res.header.RepoKey, storageKey)
187		}
188		if res.providerRepoKey != "local/widget" {
189			t.Fatalf("provider repo_key = %q, want the provider's original spelling preserved for the real check", res.providerRepoKey)
190		}
191		// Whatever the provider sent, the header reaching validateLiveSemanticHeader
192		// already carries the storage key -- so a repo_key comparison there is an
193		// identity comparison and can never report anything.
194		if !semanticRepoKeyEqual(res.header.RepoKey, storageKey) {
195			t.Fatal("unreachable: normalization guarantees equality")
196		}
197	}

