 47	// A mirror that reads only `origin` computes local/<basename> for that repo,
 48	// matches neither the provider's key nor the brain's storage key, and refuses a
 49	// perfectly valid snapshot — reintroducing the very bug the mirror exists to fix,
 50	// just for a narrower set of repositories.
 51	func TestSemanticIndexAcceptsGitHubRemoteNotNamedOrigin(t *testing.T) {
 52		repoDir := t.TempDir()
 53		env := semanticTestEnv(t, repoDir)
 54		// origin is a non-GitHub mirror; the GitHub remote is `upstream`.
 55		remotes := map[string]string{
 56			"origin":   "https://gitlab.com/acme/widget.git",
 57			"upstream": "git@github.com:acme/widget.git",
 58		}
 59		// entire-graph therefore stamps the GitHub key, not local/<base>.
 60		snapshot := `{"schema_version":"1.0","provider":"entire-graph","provider_version":"0.1.0","repo_key":"gh/acme/widget","commit":"aaa111","tree":"tree111","capabilities":["go"],"warnings":[],"partial_failures":[]}
 61	{"record_type":"symbol","id":"gh/acme/widget:go:internal/auth/token.go:function:auth.ValidateToken","kind":"function","name":"ValidateToken","qualified_name":"auth.ValidateToken","file_path":"internal/auth/token.go","start_line":10,"end_line":20,"signature":"func ValidateToken(token string) error","language":"Go","stable_id_version":"1"}
 62	{"record_type":"summary","warnings":[],"partial_failures":[]}
 63	`
 64		runner := semanticMultiRemoteFixtureRunner(repoDir, snapshot, remotes)
 65		cmd := &cobra.Command{Use: "index"}
 66		opts := Options{Env: env, Runner: runner, Now: time.Now}
 67	
 68		if err := runSemanticIndex(cmd.Context(), cmd, opts, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
 69			t.Fatalf("index a repo whose GitHub remote is named upstream: %v", err)
 70		}
 71		// Brain's storage key still comes from origin; the artifact is normalized to it.
 72		if got := persistedSnapshotRepoKey(t, env, "gl/acme/widget"); got != "gl/acme/widget" {
 73			t.Fatalf("persisted snapshot repo_key = %q, want gl/acme/widget", got)
 74		}
