112	// TestDoctorReportedRepoKeyIsAuthoritative: when the installed provider reports
113	// its own repo_key from `graph doctor --json`, that answer beats the brain's
114	// reimplementation of the provider rule. The provider is the process that will
115	// stamp the header, so it cannot be wrong about its own key — whereas the mirror
116	// is a copy that can drift the moment entire-graph's rule changes.
117	//
118	// Here the provider uses a rule the brain has never heard of. The mirror would
119	// compute local/<base> and reject the snapshot; the handshake accepts it.
120	func TestDoctorReportedRepoKeyIsAuthoritative(t *testing.T) {
121		repoDir := t.TempDir()
122		env := semanticTestEnv(t, repoDir)
123		const futureKey = "sr/acme/widget" // a forge slug this brain's mirror does not know
124		snapshot := `{"schema_version":"1.0","provider":"entire-graph","provider_version":"9.9.9","repo_key":"` + futureKey + `","commit":"aaa111","tree":"tree111","capabilities":["go"],"warnings":[],"partial_failures":[]}
