141	// what is accepted, it does not disable the guard. When the doctor names this
142	// repository's key, a snapshot carrying a DIFFERENT key is still refused — and
143	// the refusal names the doctor's answer, since that is now the authority.
144	func TestDoctorReportedRepoKeyStillRejectsAForeignSnapshot(t *testing.T) {
