 29	// semanticRepoKeyFixtureRunner is semanticFixtureRunner with the repository's
 30	// origin remote replaced (or removed, when originURL is empty), so the brain
 31	// derives a storage key that the provider cannot reproduce.
 32	func semanticRepoKeyFixtureRunner(repoDir, originURL, snapshot string) *fakeCommandRunner {
 33		runner := semanticFixtureRunner(repoDir, snapshot)
 34		if originURL == "" {
 35			runner.responses[fakeCommandKey("git", "remote", "get-url", "origin")] = fakeCommandResponse{
 36				stderr: "error: No such remote 'origin'\n",
 37				err:    errors.New("exit status 2"),
 38			}
 39		} else {
 40			runner.responses[fakeCommandKey("git", "remote", "get-url", "origin")] = fakeCommandResponse{stdout: originURL + "\n"}
 41		}
 42		// entire-graph lists every remote URL (origin first) when deriving its key.
 43		runner.responses[fakeCommandKey("git", "config", "--get-regexp", `^remote\..*\.url$`)] = fakeCommandResponse{
 44			stdout: func() string {
 45				if originURL == "" {
 46					return ""
 47				}
 48				return "remote.origin.url " + originURL + "\n"
 49			}(),
 50		}
 51		return runner
 52	}
