160	func TestProviderRepoKeyMirrorsEntireGraphRule(t *testing.T) {
161		for name, tc := range map[string]struct {
162			remotes []string
163			repoDir string
164			want    string
165		}{
166			"no remote":            {remotes: nil, repoDir: "/src/My Repo", want: "local/My Repo"},
