184	// TestProviderRepoKeyMatchesInstalledEntireGraph is the differential test that
185	// keeps the mirrored rule honest against the real provider. It is skipped when
186	// no `entire` binary is installed.
187	func TestProviderRepoKeyMatchesInstalledEntireGraph(t *testing.T) {
188		bin, err := exec.LookPath("entire")
189		if err != nil {
190			t.Skip("entire binary not installed")
191		}
192		repoDir := t.TempDir()
193		run := func(args ...string) {
194			t.Helper()
195			cmd := exec.Command("git", args...)
196			cmd.Dir = repoDir
197			if out, err := cmd.CombinedOutput(); err != nil {
198				t.Fatalf("git %v: %v: %s", args, err, out)
199			}
200		}
201		run("init", "-q", "-b", "main", ".")
202		run("config", "user.email", "t@example.com")
203		run("config", "user.name", "t")
204		if err := os.WriteFile(filepath.Join(repoDir, "main.go"), []byte("package main\n\nfunc main() {}\n"), 0o600); err != nil {
205			t.Fatalf("write source: %v", err)
206		}
207		run("add", "-A")
208		run("commit", "-qm", "init")
209	
210		for _, origin := range []string{"", "https://gitlab.com/acme/widget.git", "git@github.com:entireio/cli.git"} {
211			remotes := []string(nil)
212			if origin == "" {
213				_ = exec.Command("git", "-C", repoDir, "remote", "remove", "origin").Run()
214			} else {
215				_ = exec.Command("git", "-C", repoDir, "remote", "remove", "origin").Run()
216				run("remote", "add", "origin", origin)
217				remotes = []string{origin}
218			}
219			ctx, cancel := context.WithTimeout(context.Background(), 120*time.Second)
220			cmd := exec.CommandContext(ctx, bin, "graph", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network")
221			cmd.Dir = repoDir
222			out, err := cmd.Output()
223			cancel()
224			if err != nil {
225				t.Skipf("entire graph snapshot unavailable: %v", err)
226			}
227			line, _, _ := strings.Cut(string(out), "\n")
228			var header semanticHeader
229			if err := json.Unmarshal([]byte(line), &header); err != nil {
230				t.Fatalf("parse provider header: %v", err)
231			}
232			if got := providerRepoKeyFromRemotes(remotes, repoDir); got != header.RepoKey {
233				t.Fatalf("origin %q: mirrored rule = %q, installed provider = %q", origin, got, header.RepoKey)
234			}
235		}
236	}

