 12	// TestValidateSemanticSchemaFollowsTheTolerantReaderContract pins ADR 0001's
 13	// tolerant-reader rules: accept any supported-major minor, refuse an unknown
 14	// major, and refuse a version that is not a well-formed major.minor at all.
 15	func TestValidateSemanticSchemaFollowsTheTolerantReaderContract(t *testing.T) {
 16		t.Parallel()
 17		for _, tc := range []struct {
 18			version string
 19			wantErr bool
 20		}{
 21			{version: "1.0"},
 22			{version: "1.1"},
 23			{version: "1.2"},
 24			{version: "1.17"},
 25			{version: "1.2.3"},
 26			{version: "", wantErr: true},
 27			{version: "1", wantErr: true},
 28			{version: "2.0", wantErr: true},
 29			{version: "0.9", wantErr: true},
 30			// A minor that is not a number is not an additive minor: the contract
 31			// says major.minor, and silently accepting anything after the dot means
 32			// a malformed header rides straight into the store.
 33			{version: "1.abc", wantErr: true},
 34			{version: "1.", wantErr: true},
 35			{version: "x.1", wantErr: true},
 36		} {
 37			err := validateSemanticSchema(tc.version)
 38			if tc.wantErr && err == nil {
 39				t.Fatalf("validateSemanticSchema(%q) = nil, want an error", tc.version)
 40			}
 41			if !tc.wantErr && err != nil {
 42				t.Fatalf("validateSemanticSchema(%q) = %v, want nil", tc.version, err)
 43			}
 44		}
 45	}
 46	
 47	// TestSemanticSchemaErrorsNameTheSupportedRange keeps the operator-facing text
 48	// useful: a rejection must say what this build DOES support, not only what it
 49	// received.
 50	func TestSemanticSchemaErrorsNameTheSupportedRange(t *testing.T) {
 51		t.Parallel()
 52		for _, version := range []string{"2.0", "", "1.abc"} {
 53			err := validateSemanticSchema(version)
 54			if err == nil {
 55				t.Fatalf("validateSemanticSchema(%q) = nil, want an error", version)
 56			}
 57			if !strings.Contains(err.Error(), semanticSupportedSchemaRange) {
 58				t.Fatalf("error for %q does not name the supported range %q: %v", version, semanticSupportedSchemaRange, err)
 59			}
 60		}
 61	}
 62	
 63	// TestSemanticSchemaNewerMinorWarns is ADR 0001 rule 3: a newer supported-major
 64	// minor is accepted, but the consumer must WARN, because additive facts it does
 65	// not know about may have been skipped. Silently accepting is not compliance.
 66	func TestSemanticSchemaNewerMinorWarns(t *testing.T) {
 67		t.Parallel()
 68		for _, tc := range []struct {
 69			version  string
 70			wantWarn bool
 71		}{
 72			{version: "1.0"},
 73			{version: semanticSchemaVersion},
 74			{version: "1.99", wantWarn: true},
 75		} {
 76			warning := semanticSchemaMinorSkewWarning(tc.version)
 77			if tc.wantWarn && warning == nil {
 78				t.Fatalf("schema %q produced no newer-minor warning", tc.version)
 79			}
 80			if !tc.wantWarn && warning != nil {
 81				t.Fatalf("schema %q produced an unexpected warning: %+v", tc.version, warning)
 82			}
 83			if warning == nil {
 84				continue
 85			}
 86			for _, want := range []string{tc.version, semanticSchemaVersion} {
 87				if !strings.Contains(warning.Detail, want) {
 88					t.Fatalf("newer-minor warning does not name %q: %+v", want, warning)
 89				}
 90			}
 91		}
 92	}
 93	
 94	// TestSemanticIndexRecordsNewerMinorWarning proves the warning actually reaches
 95	// the recorded index rather than being computed and dropped.
 96	func TestSemanticIndexRecordsNewerMinorWarning(t *testing.T) {
 97		t.Parallel()
 98		repoDir := t.TempDir()
 99		env := semanticTestEnv(t, repoDir)
100		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.99"))
101		cmd := &cobra.Command{Use: "index"}
102		if err := runSemanticIndex(cmd.Context(), cmd, Options{
103			Version: "test", Env: env, Runner: runner, Now: time.Now,
104		}, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
105			t.Fatalf("a newer supported-major minor must be accepted: %v", err)
106		}
107		storage, err := repoStoragePaths(cmd.Context(), runner, env, repoDir)
108		if err != nil {
109			t.Fatalf("storage: %v", err)
110		}
111		manifest, err := loadBrainManifest(storage.BrainDir)
112		if err != nil {
113			t.Fatalf("manifest: %v", err)
114		}
115		if manifest.Sources == nil || manifest.Sources.Semantic == nil {
116			t.Fatal("manifest has no semantic source")
117		}
118		found := false
119		for _, warning := range manifest.Sources.Semantic.Warnings {
120			if warning.Code == "provider_schema_newer_minor" {
121				found = true
122			}
123		}
124		if !found {
125			t.Fatalf("index did not record a provider_schema_newer_minor warning: %+v", manifest.Sources.Semantic.Warnings)
126		}
127	}
