129	// TestSemanticStaleReportDegradesOnNewerMinor pins the second sink for the
130	// same rule. Recording the warning at index time is not enough on its own: the
131	// "provider" freshness axis is what `entire brain doctor`/`status` and every
132	// semantic read command consult, and an index built from a snapshot this build
133	// only partly understands must read as degraded there rather than a clean "ok".
134	func TestSemanticStaleReportDegradesOnNewerMinor(t *testing.T) {
135		t.Parallel()
136		repoDir := t.TempDir()
137		env := semanticTestEnv(t, repoDir)
138		// The manifest's recorded schema_version and the on-disk snapshot must
139		// agree (every freshness check revalidates the snapshot against the
140		// manifest), so index a real 1.99 provider snapshot rather than patching
141		// the manifest alone.
142		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.99"))
143		cmd := &cobra.Command{Use: "index"}
144		if err := runSemanticIndex(cmd.Context(), cmd, Options{
145			Version: "test", Env: env, Runner: runner, Now: time.Now,
146		}, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
147			t.Fatalf("index: %v", err)
148		}
149	
150		report, err := semanticStaleReport(cmd.Context(), Options{Env: env, Runner: runner}, repoDir)
151		if err != nil {
152			t.Fatalf("stale: %v", err)
153		}
154		provider := report.Axes["provider"]
155		if provider.State != "degraded" {
156			t.Fatalf("provider axis = %+v, want degraded for a newer provider minor", provider)
157		}
158		for _, want := range []string{"1.99", semanticSchemaVersion} {
159			if !strings.Contains(provider.Detail, want) {
160				t.Fatalf("provider axis detail does not name %q: %+v", want, provider)
161			}
162		}
163		if report.Severity != "degraded" {
164			t.Fatalf("severity = %s, want degraded", report.Severity)
165		}
166	}
167	
168	// TestSemanticStaleReportSilentAtSupportedMinor is the negative case for that
169	// axis: at the newest minor this build fully ingests, nothing about schema skew
170	// may appear in the provider axis.
171	func TestSemanticStaleReportSilentAtSupportedMinor(t *testing.T) {
172		t.Parallel()
173		repoDir := t.TempDir()
174		env := semanticTestEnv(t, repoDir)
175		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot(semanticSchemaVersion))
176		cmd := &cobra.Command{Use: "index"}
177		if err := runSemanticIndex(cmd.Context(), cmd, Options{
178			Version: "test", Env: env, Runner: runner, Now: time.Now,
179		}, semanticIndexOptions{graphBinary: "entire"}, repoDir); err != nil {
180			t.Fatalf("index: %v", err)
181		}
182	
183		report, err := semanticStaleReport(cmd.Context(), Options{Env: env, Runner: runner}, repoDir)
184		if err != nil {
185			t.Fatalf("stale: %v", err)
186		}
187		if detail := report.Axes["provider"].Detail; strings.Contains(detail, "minors are additive") {
188			t.Fatalf("provider axis reports schema skew at the supported minor: %q", detail)
189		}
190	}
