192	// TestBundleImportRecordsNewerMinorWarning pins the third sink. A bundle
193	// carries a snapshot this build ingests only partially in exactly the same way
194	// a live provider does, so the import must succeed (tolerant reader) and leave
195	// the warning on the semantic source it persists, rather than accepting the
196	// bundle with no trace.
197	func TestBundleImportRecordsNewerMinorWarning(t *testing.T) {
198		t.Parallel()
199		repoDir := t.TempDir()
200		env := semanticTestEnv(t, repoDir)
201		runner := semanticFixtureRunner(repoDir, semanticFixtureSnapshot("1.99"))
202		archive := filepath.Join(t.TempDir(), "newer-minor.tar")
203		writeTestBundle(t, archive, map[string]string{
204			exportManifestFileName:                      `{"schema_version":3,"repo_key":"gh/example/repo","sources":{"semantic":{"schema_version":"1.99","snapshot_path":"semantic/snapshots/aaa111/snapshot.ndjson"}}}`,
205			"semantic/snapshots/aaa111/snapshot.ndjson": semanticFixtureSnapshot("1.99"),
206		})
207		if err := runSemanticBundleImport((&cobra.Command{}).Context(), &cobra.Command{Use: "bundle import"}, Options{
208			Version: "test", Env: env, Runner: runner, Now: time.Now,
209		}, archive, bundleSHA256(t, archive), false); err != nil {
210			t.Fatalf("a newer supported-major minor must import: %v", err)
211		}
212		source := mustSemanticSource(t, env)
213		found := false
214		for _, warning := range source.Warnings {
215			if warning.Code == "provider_schema_newer_minor" {
