146		records := []string{
147			`{"record_type":"file","file_path":"a.go","language":"Go"}`,
148			`{"record_type":"symbol","id":"s1","kind":"function","name":"A","file_path":"a.go","stable_id_version":"1"}`,
149			`{"record_type":"relation","from_id":"caller","to_id":"s1","type":"CALLS","confidence":1}`,
150			`{"record_type":"summary","languages":["Go"]}`,
151		}
152		pr, pw := io.Pipe()
153		proceed := make(chan struct{})
154		cfg := semanticStreamScanConfig{
155			onRecord: func(string) {
156				// Block until the producer acknowledges, proving the consumer reaches
157				// this record before the next one is even written. If the scanner
158				// buffered the whole stream first, the producer would never write
159				// past record 1 and this would not complete.
