164			fmt.Fprintln(pw, semanticStreamLeanHeader)
165			for _, rec := range records {
166				fmt.Fprintln(pw, rec)
167				<-proceed
168			}
169			_ = pw.Close()
170		}()
171	
172		done := make(chan semanticStreamResult, 1)
173		go func() {
174			res, err := scanSemanticStream(pr, io.Discard, cfg)
175			if err != nil {
176				t.Errorf("scan stream: %v", err)
177			}
178			done <- res
179		}()
180	
181		select {
182		case res := <-done:
