145	func TestScanSemanticStreamProcessesRecordsIncrementally(t *testing.T) {
146		records := []string{
147			`{"record_type":"file","file_path":"a.go","language":"Go"}`,
148			`{"record_type":"symbol","id":"s1","kind":"function","name":"A","file_path":"a.go","stable_id_version":"1"}`,
149			`{"record_type":"relation","from_id":"caller","to_id":"s1","type":"CALLS","confidence":1}`,
150			`{"record_type":"summary","languages":["Go"]}`,
151		}
152		pr, pw := io.Pipe()
153		proceed := make(chan struct{})
154		cfg := semanticStreamScanConfig{
155			onRecord: func(string) {
156				// Block until the producer acknowledges, proving the consumer reaches
157				// this record before the next one is even written. If the scanner
158				// buffered the whole stream first, the producer would never write
159				// past record 1 and this would not complete.
160				proceed <- struct{}{}
161			},
162		}
163		go func() {
164			fmt.Fprintln(pw, semanticStreamLeanHeader)
165			for _, rec := range records {
166				fmt.Fprintln(pw, rec)
167				<-proceed
168			}
169			_ = pw.Close()
170		}()
171	
172		done := make(chan semanticStreamResult, 1)
173		go func() {
174			res, err := scanSemanticStream(pr, io.Discard, cfg)
175			if err != nil {
176				t.Errorf("scan stream: %v", err)
177			}
178			done <- res
179		}()
180	
181		select {
182		case res := <-done:
183			if res.counts.Symbols != 1 || res.counts.Relations != 1 {
184				t.Fatalf("unexpected counts: %+v", res.counts)
185			}
186		case <-time.After(10 * time.Second):
187			t.Fatal("streaming did not complete; records were not processed incrementally")
188		}
189	}
