214	func (g *generatedSemanticStream) Read(p []byte) (int, error) {
215		for len(g.pending) == 0 {
216			line, ok := g.line(g.i)
217			if !ok {
218				return 0, io.EOF
219			}
220			g.i++
221			g.pending = []byte(line + "\n")
222		}
223		n := copy(p, g.pending)
224		g.pending = g.pending[n:]
225		g.bytes += int64(n)
226		return n, nil
227	}
