201	func (g *generatedSemanticStream) line(i int) (string, bool) {
202		switch {
203		case i == 0:
204			return semanticStreamLeanHeader, true
205		case i <= g.n:
206			return fmt.Sprintf(`{"record_type":"relation","from_id":"caller-%d","to_id":"callee-%d","type":"CALLS","confidence":1}`, i, i), true
207		case i == g.n+1:
208			return `{"record_type":"summary","languages":["Go"]}`, true
209		default:
210			return "", false
211		}
212	}
