    12	// TestValidateSemanticSchemaFollowsTheTolerantReaderContract pins ADR 0001's
    13	// tolerant-reader rules: accept any supported-major minor, refuse an unknown
    14	// major, and refuse a version that is not a well-formed major.minor at all.
    15	func TestValidateSemanticSchemaFollowsTheTolerantReaderContract(t *testing.T) {
    16		t.Parallel()
    17		for _, tc := range []struct {
    18			version string
    19			wantErr bool
    20		}{
    21			{version: "1.0"},
    22			{version: "1.1"},
    23			{version: "1.2"},
    24			{version: "1.17"},
    25			{version: "1.2.3"},
    26			{version: "", wantErr: true},
    27			{version: "1", wantErr: true},
    28			{version: "2.0", wantErr: true},
    29			{version: "0.9", wantErr: true},
    30			// A minor that is not a number is not an additive minor: the contract
    31			// says major.minor, and silently accepting anything after the dot means
    32			// a malformed header rides straight into the store.
    33			{version: "1.abc", wantErr: true},
    34			{version: "1.", wantErr: true},
    35			{version: "x.1", wantErr: true},
    36		} {
