    38			if tc.wantErr && err == nil {
    39				t.Fatalf("validateSemanticSchema(%q) = nil, want an error", tc.version)
    40			}
    41			if !tc.wantErr && err != nil {
    42				t.Fatalf("validateSemanticSchema(%q) = %v, want nil", tc.version, err)
    43			}
    44		}
    45	}
