   229	func TestScanSemanticStreamDoesNotBufferProportionally(t *testing.T) {
   230		if raceEnabled {
   231			// The race detector instruments allocations, which both distorts heap
   232			// measurements and makes a large synthetic stream slow; the bounded-memory
   233			// property this asserts is independent of data races.
   234			t.Skip("heap-bounds test is unreliable and slow under -race")
   235		}
   236		const records = 50_000
   237		gen := &generatedSemanticStream{n: records}
   238	
   239		var before, after runtime.MemStats
   240		runtime.GC()
   241		runtime.ReadMemStats(&before)
   242	
   243		res, err := scanSemanticStream(gen, io.Discard, semanticStreamScanConfig{})
   244		if err != nil {
   245			t.Fatalf("scan stream: %v", err)
   246		}
   247	
   248		runtime.GC()
   249		runtime.ReadMemStats(&after)
   250	
   251		if res.counts.Relations != records {
   252			t.Fatalf("relation count = %d, want %d", res.counts.Relations, records)
   253		}
   254		heapDelta := int64(after.HeapAlloc) - int64(before.HeapAlloc)
   255		if heapDelta < 0 {
   256			heapDelta = 0
   257		}
   258		// The stream is tens of megabytes; retained heap must be a tiny fraction of
   259		// it (relations are not retained in any map, so growth should be ~flat).
   260		if heapDelta*4 > gen.bytes {
   261			t.Fatalf("retained heap %d bytes is not bounded vs %d streamed bytes", heapDelta, gen.bytes)
   262		}
   263	}
