548			`{"record_type":"symbol","id":"s1","kind":"function","name":"A","file_path":"a.go","stable_id_version":"1"}` + "\n"
549		runner := &fakeCommandRunner{responses: map[string]fakeCommandResponse{
550			fakeCommandKey("entire", "graph", "snapshot", "--repo", repoDir, "--format", "ndjson", "--no-network"): {
551				stdout: noSummary,
552			},
553		}}
554		out := &bytes.Buffer{}
